INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q11794916', 'Siege of Tyre', 'The siege of Tyre is usually assumed to have been waged for 13 years from 586 to 573 BC by Nebuchadnezzar II of Babylon. The siege of Tyre, in Phoenicia, has a significant connection to the Book of Ezekiel which in chapter 26 announces that the city will soon fall to the Babylonian forces, while chapter 29 states that the siege was partially unsuccessful.', -586, NULL, NULL, -573, NULL, NULL, 'year', '586 BCE – 573 BCE', 37, 'https://en.wikipedia.org/wiki/Siege_of_Tyre_(586%E2%80%93573_BC)'),
  ('Q815233', 'Siege of Tyre', 'The siege of Tyre was carried out by Alexander the Great in 332 BC during his campaigns against the Persians. At first, the Macedonian army was unable to capture the city of Tyre, which was a strategic coastal base on the Mediterranean Sea, through conventional means because it was on an island that was 1 kilometer off the coast of modern-day Lebanon (at the time Phoenicia) and had walls right up to the sea.', -332, 1, NULL, -332, 7, NULL, 'month', 'January 332 BCE – July 332 BCE', 67, 'https://en.wikipedia.org/wiki/Siege_of_Tyre_(332_BC)'),
  ('Q17028780', 'Revolt of Tyre', 'The Revolt of Tyre was an anti-Fatimid rebellion by the populace of the city of Tyre, in modern Lebanon. It began in 996, when the people, led by an ordinary sailor named ''Allaqa, rose up against the Fatimid government.', 996, NULL, NULL, 998, 5, NULL, 'year', '996 – May 998', 37, 'https://en.wikipedia.org/wiki/Revolt_of_Tyre_(996%E2%80%93998)'),
  ('Q1723525', 'Siege of Tripoli', 'The siege of Tripoli lasted from 1102 until 12 July 1109. It took place on the site of the present day Lebanese city of Tripoli, in the aftermath of the First Crusade.', 1102, NULL, NULL, 1109, 7, 12, 'year', '1102 – 12 July 1109', 51, 'https://en.wikipedia.org/wiki/Siege_of_Tripoli'),
  ('Q3431465', 'Siege of Sidon', 'The siege of Sidon occurred in 1110 in the aftermath of the First Crusade. The coastal city of Sidon was captured by the forces of Baldwin I of Jerusalem and Sigurd I of Norway, with assistance from Ordelafo Faliero, Doge of Venice.', 1110, 10, 19, 1110, 12, 5, 'day', '19 October 1110 – 5 December 1110', 53, 'https://en.wikipedia.org/wiki/Siege_of_Sidon'),
  ('Q636520', 'Battle of Marj Ayyun', 'The Battle of Marj Ayyun was a military confrontation fought at Marj Ayyun near the Litani River (modern-day Lebanon) in June 1179 between the Kingdom of Jerusalem under Baldwin IV and the Ayyubid armies under the leadership of Saladin. It ended in a decisive victory for the Muslims and is considered the first in the long series of Islamic victories under Saladin against the Christians.', 1179, 6, 10, NULL, NULL, NULL, 'day', '10 June 1179', 60, 'https://en.wikipedia.org/wiki/Battle_of_Marj_Ayyun'),
  ('Q2176345', 'Siege of Tyre', 'The siege of Tyre took place from 12 November 1187 to 1 January 1188. An Ayyubid army commanded by Saladin made an amphibious assault on the city, defended by Conrad of Montferrat.', 1187, 11, 12, 1188, 1, 1, 'day', '12 November 1187 – 1 January 1188', 57, 'https://en.wikipedia.org/wiki/Siege_of_Tyre_(1187)'),
  ('Q7510468', 'Siege of Tripoli', 'The Truce of Tripoli was an agreement signed in late May 1271 between the Mamluk Sultan Baybars and the Count of Tripoli Bohemond VI of Antioch. Baybars initially wanted to attack the County of Tripoli, but after the arrival of a new Ninth Crusade, he made a truce that lasted ten years with terms to allow Baybars to retain his conquests.', 1271, 5, 9, 1271, 5, NULL, 'day', '9 May 1271 – May 1271', 41, 'https://en.wikipedia.org/wiki/Truce_of_Tripoli_(1271)'),
  ('Q5432166', 'Fall of Tripoli', 'The Fall of Tripoli was the capture and destruction of the Crusader state of the County of Tripoli (now parts of Lebanon and Syria) by the Mamluk Sultanate of Egypt. The battle occurred in 1289 and was an important event in the Crusades, as it marked the capture of one of the few remaining major Crusader possessions.', 1289, 3, NULL, 1289, 4, 26, 'month', 'March 1289 – 26 April 1289', 53, 'https://en.wikipedia.org/wiki/Fall_of_Tripoli_(1289)'),
  ('Q4870306', 'Battle of Anjar', 'The Battle of Anjar was fought on 1 November 1623 between the army of Fakhr al-Din II and a coalition army led by the governor of Damascus Mustafa Pasha.', 1623, 11, 1, NULL, NULL, NULL, 'day', '1 November 1623', 37, 'https://en.wikipedia.org/wiki/Battle_of_Anjar'),
  ('Q4090324', 'Battle of Beirut', 'The Battle of Beirut was a naval battle off the coast of Beirut during the Italo-Turkish War. Italian fears that the Ottoman naval forces at Beirut could be used to threaten the approach to the Suez Canal led the Italian military to order the destruction of the Ottoman naval presence in the area.', 1912, 2, 24, NULL, NULL, NULL, 'day', '24 February 1912', 51, 'https://en.wikipedia.org/wiki/Battle_of_Beirut_(1912)'),
  ('Q4871340', 'Battle of Jisr Benat Yakub', 'The Battle of Jisr Benat Yakub was fought on 27 September 1918 at the beginning of the pursuit by the Desert Mounted Corps of the retreating remnants of the Yildirim Army Group towards Damascus during the Sinai and Palestine campaign of World War I. After the Battle of Samakh and the Capture of Tiberias, which completed the Egyptian Expeditionary Force''s decisive victory in the Battle of Sharon section of the Battle of Megiddo, the Australian Mounted Division attacked and captured a series of rearguard positions. The positions were held by German and Ottoman soldiers of the Tiberias Group…', 1918, 9, 27, NULL, NULL, NULL, 'day', '27 September 1918', 37, 'https://en.wikipedia.org/wiki/Battle_of_Jisr_Benat_Yakub'),
  ('Q4870445', 'Battle of Beirut', 'The Battle of Beirut (12 July 1941) marked the end of hostilities in the Syria–Lebanon campaign of World War II. The campaign saw the initial Allied deployment of 2 brigades of the Australian 7th Division, a brigade from the 1st British Cavalry Division, the 5th Indian Infantry Brigade which was deployed immediately from Eritrea after the surrender of the Duke of Aosta, several armoured and air units of the British 6th Division, a special commando force (C battalion of the Special Service Brigade) and 6 battalions of the 1st Free French Division. On 8 July, even before the fall of Damour,…', 1941, 7, 12, NULL, NULL, NULL, 'day', '12 July 1941', 37, 'https://en.wikipedia.org/wiki/Battle_of_Beirut_(1941)'),
  ('Q4871328', 'Battle of Jezzine', 'The Battle of Jezzine (13 June 1941) was part of the Australian 7th Division''s advance on Beirut during the five-week-long Syria-Lebanon campaign by the Allies against Vichy French forces in Syria and Lebanon. Jezzine, Lebanon, is about halfway between the Lebanese border with Mandatory Palestine and Beirut.', 1941, 6, 13, NULL, NULL, NULL, 'day', '13 June 1941', 34, 'https://en.wikipedia.org/wiki/Battle_of_Jezzine_(1941)'),
  ('Q1452633', 'Hula massacre', 'The Hula massacre took place between 31 October and 1 November 1948 in Hula, a village in Lebanon 3 km west of Kibbutz Manara, not far from the Litani River. It was captured on October 24 by the Carmeli Brigade of the Israel Defense Forces without any resistance.', 1948, 11, 1, NULL, NULL, NULL, 'day', '1 November 1948', 47, 'https://en.wikipedia.org/wiki/Hula_massacre'),
  ('Q208484', 'Lebanese Civil War', 'The Lebanese Civil War (Arabic: الحرب الأهلية اللبنانية, al-ḥarb al-ahliyyah al-libnāniyyah) was a multifaceted armed conflict fought in Lebanon from 1975 to 1990. It resulted in an estimated 120,000 deaths, displaced nearly one million people, and caused widespread destruction across the country.', 1975, 4, 13, 1990, 10, 13, 'day', '13 April 1975 – 13 October 1990', 79, 'https://en.wikipedia.org/wiki/Lebanese_Civil_War'),
  ('Q661994', 'Black Saturday', 'Black Saturday (Arabic: السبت الأسود; French: Samedi noir) was the massacre of between 150 and 200 Lebanese Muslim and Druze civilians by Phalangist forces on Saturday 6 December 1975, during the early stages of the Lebanese Civil War. It set a precedent for later outbreaks of violence such as the Battle of the Hotels, the Karantina massacre and the Damour massacre.', 1975, 12, 6, NULL, NULL, NULL, 'day', '6 December 1975', 43, 'https://en.wikipedia.org/wiki/Black_Saturday_(Lebanon)'),
  ('Q64876', 'Syrian occupation of Lebanon', 'The Syrian occupation of Lebanon lasted from 31 May 1976, beginning with the Syrian intervention in the Lebanese Civil War, until 30 April 2005. This period saw significant Syrian military and political influence over Lebanon, impacting its governance, economy, and society.', 1976, 5, 31, 2005, 4, 30, 'day', '31 May 1976 – 30 April 2005', 47, 'https://en.wikipedia.org/wiki/Syrian_occupation_of_Lebanon'),
  ('Q1351462', 'Damour massacre', 'The Damour massacre took place on 20 January 1976, during the 1975–1990 Lebanese Civil War. Damour, a Maronite Christian town on the main highway south of Beirut, was attacked by militants of the Palestine Liberation Organisation and as-Sa''iqa.', 1976, 1, 20, NULL, NULL, NULL, 'day', '20 January 1976', 58, 'https://en.wikipedia.org/wiki/Damour_massacre'),
  ('Q1907402', 'Karantina massacre', 'The Karantina massacre (Arabic: مجزرة الكرنتينا; French: Massacre de La Quarantaine/Karantina) took place on 18 January 1976, early in the Lebanese Civil War. La Quarantine, known in Arabic as "Karantina", was a Muslim-inhabited district in mostly Christian East Beirut controlled by forces of the Palestine Liberation Organization (PLO) and the Lebanese National Movement (LNM), and inhabited by Palestinians, Kurds, Armenians, Syrians, and Lebanese Muslims.', 1976, 1, 18, NULL, NULL, NULL, 'day', '18 January 1976', 48, 'https://en.wikipedia.org/wiki/Karantina_massacre'),
  ('Q2359563', 'Tel al-Zaatar massacre', 'The Tel al-Zaatar massacre was the killing of approximately 1,500 Palestinians and Lebanese Muslims in the Tel al-Zaatar refugee camp in Beirut, Lebanon on 12 August 1976. The massacre occurred during the Lebanese Civil War, after the Tel al-Zaatar refugee camp had been under siege since January 1976 by Lebanese Christian militias of the Lebanese Front led by the Kataeb Phalangists.', 1976, 8, 12, NULL, NULL, NULL, 'day', '12 August 1976', 56, 'https://en.wikipedia.org/wiki/Tel_al-Zaatar_massacre'),
  ('Q2992532', 'Bab al-Tabbaneh–Jabal Mohsen conflict', 'The Bab al-Tabbaneh–Jabal Mohsen conflict was a recurring conflict between the Sunni Muslim residents of the Bab-al-Tabbaneh neighbourhood and the Alawite residents of the Jabal Mohsen neighbourhood of Tripoli, Lebanon from 1976 through 2015. Residents of the two neighbourhoods became rivals during the Lebanese Civil War and frequently engaged in violence.', 1976, NULL, NULL, 2015, NULL, NULL, 'year', '1976–2015', 37, 'https://en.wikipedia.org/wiki/Bab_al-Tabbaneh%E2%80%93Jabal_Mohsen_conflict'),
  ('Q4872937', 'Battle of the Hotels', 'The Battle of the Hotels (Arabic: معركة الفنادق, Maʿrakah al-Fanādiq) was a subconflict within the 1975–77 phase of the Lebanese Civil War that occurred in the Minet-el-Hosn hotel district of downtown Beirut. This area was one of the first major battles of the war that began in April 1975.', 1976, 4, 2, 1976, 3, NULL, 'day', '2 April 1976 – March 1976', 43, 'https://en.wikipedia.org/wiki/Battle_of_the_Hotels'),
  ('Q7015178', 'Chekka massacre', 'The Chekka Massacre (Arabic: مجزرة شكا) occurred on July 5, 1976, when Palestinian and Lebanese National Movement fighters killed approximately 200 people in the Christian towns of Chekka and Hamat during the Lebanese Civil War. The attack was launched from Tripoli by Palestinian militants and members of an Islamist group Jund Allah.', 1976, 7, 5, NULL, NULL, NULL, 'day', '5 July 1976', 37, 'https://en.wikipedia.org/wiki/Chekka_massacre'),
  ('Q5348566', 'Ehden massacre', 'The Ehden massacre (Arabic: مجزرة إهدن, romanized: Majzarat Ehden) took place on 13 June 1978, during the 1975–1990 Lebanese Civil War. It was an inter-Christian attack between Maronite clans.', 1978, 6, 13, NULL, NULL, NULL, 'day', '13 June 1978', 39, 'https://en.wikipedia.org/wiki/Ehden_massacre'),
  ('Q208199', 'Sabra and Shatila massacre', 'From 16 to 18 September 1982, between 1,300 and 3,500 civilians—mostly Palestinians and Lebanese Shias—were killed in Beirut''s Sabra neighbourhood and the adjacent Shatila refugee camp by the Lebanese Forces, one of the main Christian militias in Lebanon, with the support of the Israel Defense Forces (IDF). In June 1982, Israel invaded Lebanon with the intention of rooting out the Palestine Liberation Organization (PLO).', 1982, 9, 16, 1982, 9, 18, 'day', '16 September 1982 – 18 September 1982', 72, 'https://en.wikipedia.org/wiki/Sabra_and_Shatila_massacre'),
  ('Q2617818', 'Siege of Beirut', 'During the 1982 Lebanon War, the city of Beirut was besieged by Israel following the breakdown of the ceasefire that had been imposed by the United Nations amidst the Lebanese Civil War. Beginning in mid-June, the two-month-long siege resulted in thousands of civilian deaths and the expulsion of the Palestine Liberation Organization (PLO) from Beirut and the rest of Lebanon.', 1982, 6, 14, 1982, 8, 21, 'day', '14 June 1982 – 21 August 1982', 56, 'https://en.wikipedia.org/wiki/Siege_of_Beirut'),
  ('Q2904564', 'Battle of the Beaufort', 'The Battle of the Beaufort was fought between the Israel Defense Forces (IDF) and the Palestine Liberation Organization (PLO) on June 6, 1982, over Beaufort Castle, Lebanon. It was one of the first clashes of the 1982 Lebanon War and resulted in the IDF capturing the castle.', 1982, 6, 6, 1982, 6, 7, 'day', '6 June 1982 – 7 June 1982', 34, 'https://en.wikipedia.org/wiki/Battle_of_the_Beaufort'),
  ('Q321851', 'May 17 Agreement', 'The May 17 Agreement of 1983 was an agreement signed between Lebanon and Israel during the Lebanese Civil War on May 17, 1983, after Israel invaded Lebanon to end cross border attacks and besieged Beirut in 1982. It called for the withdrawal of the Israeli Army from Beirut and provided a framework for the establishment of normal bilateral relations between the two countries.', 1983, 5, 17, NULL, NULL, NULL, 'day', '17 May 1983', 50, 'https://en.wikipedia.org/wiki/May_17_Agreement'),
  ('Q2479435', 'South Lebanon conflict', 'The South Lebanon conflict was an armed conflict that took place in Israeli-occupied southern Lebanon from 1982 or 1985 until Israel''s withdrawal in 2000. Hezbollah, along with other Shia Muslim and left-wing guerrillas, fought against Israel and its ally, the Catholic Christian-dominated South Lebanon Army (SLA).', 1985, 2, 16, 2000, 5, 25, 'day', '16 February 1985 – 25 May 2000', 60, 'https://en.wikipedia.org/wiki/South_Lebanon_conflict_(1985%E2%80%932000)'),
  ('Q2777811', 'War of the Camps', 'The War of the Camps (Arabic: حرب المخيمات, romanized: Ḥarb al-Mukhayimat), was a subconflict within the 1984–1990 phase of the Lebanese Civil War, in which the Sunni Palestinian refugee camps in Beirut were besieged by the Shia Amal militia. The "War of the Camps" was a struggle for control over West Beirut and was considered an extension of the political struggle between Syria and the Palestine Liberation Organization (PLO).', 1985, 5, 19, 1988, 7, NULL, 'day', '19 May 1985 – July 1988', 39, 'https://en.wikipedia.org/wiki/War_of_the_Camps'),
  ('Q42661822', 'The Bourj Hammoud Massacre', 'The Bourj Hammoud massacre was an armed robbery that took place in a jewelry shop in the Bourj Hammoud quarter, Lebanon, in 1985. Five people have died as a result; the three perpetrators were arrested by the Lebanese Internal Security Forces and sentenced to death but escaped from prison before they could face execution, and have vanished without trace.', 1985, 3, 28, NULL, NULL, NULL, 'day', '28 March 1985', 37, 'https://en.wikipedia.org/wiki/Bourj_Hammoud_massacre'),
  ('Q56063038', 'War of Brothers', 'The War of Brothers (Arabic: حرب الإخوة, romanized: Ḥarb al-ʾIkhwat) was a period of violent armed clashes between rivals Amal and Hezbollah, Lebanon''s main Shiite militia movements, during the final stages of the Lebanese Civil War. The fighting broke out in April 1988 and proceeded intermittently in three phases over the following years until the signing of an agreement brokered by their respective foreign backers, Ba''athist Syria and Iran, in November 1990.', 1988, 4, NULL, 1990, 11, NULL, 'month', 'April 1988 – November 1990', 34, 'https://en.wikipedia.org/wiki/War_of_Brothers'),
  ('Q7076868', 'War of Liberation (1989–1990)', 'The War of Liberation (Arabic: حرب التحرير) was a sub-conflict within the final phase of the Lebanese Civil War between 1989 and 1990, in which the Lebanese Army loyal to General and Prime Minister Michel Aoun, appointed by previous President Amine Gemayel and headquartered in eastern Beirut, fought against the western Beirut-based Syrian Armed Forces and the Lebanese Army loyal to President Elias Hrawi and Prime Minister Salim el-Hoss, appointed by the Taif Agreement. Aoun launched several offensives against the Lebanese Forces in an attempt to establish his authority over East Beirut.', 1989, 3, NULL, 1990, 10, 13, 'month', 'March 1989 – 13 October 1990', 34, 'https://en.wikipedia.org/wiki/War_of_Liberation_(1989%E2%80%931990)'),
  ('Q130379735', 'Night Time Operation', 'On 16 February 1992, Abbas al-Musawi, the secretary-general of Hezbollah, was assassinated in an Israeli airstrike on his vehicle in southern Lebanon, as part of the South Lebanon conflict (1985–2000). Israel code-named the operation Night Time Operation (Hebrew: מבצע שעת לילה).', 1992, 2, 16, NULL, NULL, NULL, 'day', '16 February 1992', 37, 'https://en.wikipedia.org/wiki/Assassination_of_Abbas_al-Musawi'),
  ('Q712897', '1996 Qana massacre', 'The Qana massacre took place on April 18, 1996, near Qana, a village in then Israeli-occupied Southern Lebanon, when the Israeli military fired artillery shells at a United Nations compound, which was sheltering around 800 Lebanese civilians, killing 106 and injuring around 116. Four Fijian United Nations Interim Force in Lebanon soldiers were also seriously injured.', 1996, 4, 18, NULL, NULL, NULL, 'day', '18 April 1996', 52, 'https://en.wikipedia.org/wiki/Qana_massacre'),
  ('Q1473919', 'Operation Grapes of Wrath', 'Operation Grapes of Wrath (Hebrew: מבצע ענבי זעם Mivtsa Enavi Zaam), known in Lebanon as the April Aggression (Arabic: عدوان نيسان, romanized: ʿUdwān Nīsān), was a seventeen-day campaign of the Israel Defense Forces (IDF) against Hezbollah in 1996 which attempted to end the Iran-backed group''s rocket attacks on northern Israeli civilian centres by forcing the group north of the Litani River, out of easy range of these civilian centres. Prior to the operation, Hezbollah had launched 151 rockets from Lebanon into Israel, killing two Israeli civilians and seriously wounding 24 other Israeli…', 1996, 4, 27, NULL, NULL, NULL, 'day', '27 April 1996', 57, 'https://en.wikipedia.org/wiki/Operation_Grapes_of_Wrath'),
  ('Q4598399', '2000–2006 Shebaa Farms conflict', 'The 2000–2006 Shebaa Farms conflict was a low-level border conflict between Israel and Hezbollah for control of Shebaa Farms, a disputed territory located on the Golan Heights–Lebanon border. Fighting between the two sides primarily consisted of Hezbollah rocket and mortar attacks on Israel and Israeli artillery barrages and airstrikes on Hezbollah in southern Lebanon.', 2000, 10, 7, 2006, 7, 12, 'day', '7 October 2000 – 12 July 2006', 43, 'https://en.wikipedia.org/wiki/2000%E2%80%932006_Shebaa_Farms_conflict'),
  ('Q184310', 'Cedar Revolution', 'The Cedar Revolution (Arabic: ثورة الأرز, romanized: thawrat al-arz), known in Lebanon as the Independence intifada (انتفاضة الاستقلال, intifadat al-istiqlal), was a chain of demonstrations in Lebanon (especially in the capital Beirut) triggered by the assassination of former Lebanese Prime Minister Rafic Hariri. The popular movement was remarkable for its avoidance of violence, peaceful approach, and its total reliance on methods of civil resistance.', 2005, 2, 14, 2005, 4, 27, 'day', '14 February 2005 – 27 April 2005', 63, 'https://en.wikipedia.org/wiki/Cedar_Revolution'),
  ('Q49104', '2006 Lebanon War', 'The 2006 Lebanon War was a 34-day armed conflict in Lebanon, fought between Hezbollah and Israel. The war started on 12 July 2006 and continued until a United Nations-brokered ceasefire went into effect in the morning on 14 August 2006, though it formally ended on 8 September 2006 when Israel lifted its naval blockade of Lebanon.', 2006, NULL, NULL, 2006, 8, 14, 'year', '2006', 81, 'https://en.wikipedia.org/wiki/2006_Lebanon_War'),
  ('Q2628614', 'Battle of Bint Jbeil', 'The Battle of Bint Jbeil was one of the main battles of the 2006 Lebanon War. Bint Jbeil is a major town of some 20,000 (mainly Shia) inhabitants in Southern Lebanon.', 2006, 7, 23, 2006, 8, 11, 'day', '23 July 2006 – 11 August 2006', 43, 'https://en.wikipedia.org/wiki/Battle_of_Bint_Jbeil_(2006)'),
  ('Q2888072', 'Battle of Ayta ash-Shab', 'The Battle of Ayta ash-Sha''b took place during the 2006 Lebanon War, when the Israel Defense Forces and the Islamic Resistance, the armed wing of Hezbollah, fought over the town of Ayta ash-Sha''b in southern Lebanon. The fighting started with the 2006 Hezbollah cross-border raid.', 2006, 8, 11, NULL, NULL, NULL, 'day', '11 August 2006', 37, 'https://en.wikipedia.org/wiki/Battle_of_Ayta_ash-Sha''b'),
  ('Q2889287', 'Battle of Maroun al-Ras', 'The Battle of Maroun al-Ras was a battle of the 2006 Lebanon War that took place in Maroun al-Ras, a small village in southern Lebanon on the border with Israel, and Jall ad-Dayr, a nearby Hezbollah stronghold. This battle was the first serious ground battle in the 2006 Lebanon war.', 2006, NULL, NULL, 2006, 7, 29, 'year', '2006', 39, 'https://en.wikipedia.org/wiki/Battle_of_Maroun_al-Ras_(2006)'),
  ('Q2573593', '2008 Lebanon conflict', 'The 2008 Lebanon conflict (or the 7 May clashes; Arabic: أحداث 7 أيار) was a brief civil war in May 2008 in Lebanon between Hezbollah and pro-government Sunnis. After the 18-month-long political crisis spiralled out of control, with the government''s decision to dismantle Hezbollah''s telecommunication system, Hezbollah seized control of majority Sunni neighborhoods in west Beirut.', 2008, 5, 7, 2008, 5, 14, 'day', '7 May 2008 – 14 May 2008', 52, 'https://en.wikipedia.org/wiki/2008_Lebanon_conflict'),
  ('Q130714', 'Syrian civil war spillover in Lebanon', 'Between 2011 and 2017, fighting from the Syrian civil war spilled over into Lebanon as opponents and supporters of the Ba''athist Syrian regime traveled to Lebanon to fight and attack each other on Lebanese soil. The Syrian conflict stoked a resurgence of sectarian violence in Lebanon, with many of Lebanon''s Sunni Muslims and Lebanon''s Christians supporting the rebels in Syria, while many of Lebanon''s Shi''a Muslims supporting the Ba''athist government of Bashar al-Assad, whose Alawite minority is usually described as a heterodox offshoot of Shi''ism.', 2011, 6, 17, 2017, 8, 28, 'day', '17 June 2011 – 28 August 2017', 53, 'https://en.wikipedia.org/wiki/Syrian_civil_war_spillover_in_Lebanon'),
  ('Q2995643', '2011 Lebanese protests', 'The 2011 Lebanese protests, also known as the Uprising of Dignity were seen as influenced by the Arab Spring. The main protests focused on calls for political reform especially against confessionalism in Lebanon.', 2011, NULL, NULL, 2011, 12, 15, 'year', '2011', 47, 'https://en.wikipedia.org/wiki/2011_Lebanese_protests'),
  ('Q17505265', 'Battle of Arsal', 'The Battle of Arsal was a major combat engagement between Lebanese forces, and Salafi jihadist militants groups from Syria at the town of Arsal in the Baalbek-Hermel Governorate of Lebanon. It involved soldiers from the Lebanese Armed Forces, Hezbollah fighters, and militants affiliated with the Al-Nusra Front and Islamic State.', 2014, 8, 7, 2014, 8, 7, 'day', '7 August 2014', 43, 'https://en.wikipedia.org/wiki/Battle_of_Arsal_(2014)'),
  ('Q20859038', '2015 Lebanese protests', 'The 2015–2016 Lebanese protests, commonly referred to as the "You Stink" movement (Arabic: مظاهرات طلعت ريحتكم ), were a series of mass demonstrations in reaction to a waste management crisis in Lebanon. The closure of the Naameh landfill, which operated beyond its intended capacity since 1997, led to the suspension of garbage collection across Beirut and Mount Lebanon.', 2015, 8, 22, 2016, NULL, NULL, 'day', '22 August 2015 – 2016', 45, 'https://en.wikipedia.org/wiki/2015%E2%80%932016_Lebanese_protests'),
  ('Q71443275', '17 October Revolution', 'The 17 October Protests, commonly referred to as the 17 October Revolution or Hirak or Thawrah (Arabic: ثورة 17 تشرين الأول, romanized: thawrat 17 tishrīn al-ʾawwal, lit. ''17 October revolution''), were a series of civil protests in Lebanon that began after the Lebanese cabinet announced financial measures on 17 October 2019. These nationwide protests were triggered by planned taxes on gasoline, tobacco, and VoIP calls on applications such as WhatsApp, but quickly expanded into a country-wide condemnation of sectarian rule, the stagnation of the economy, unemployment (which reached 46% in…', 2019, 10, 17, NULL, NULL, NULL, 'day', '17 October 2019', 55, 'https://en.wikipedia.org/wiki/17_October_Revolution'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q98073118', '2020 Beirut explosions', 'On 4 August 2020, a major explosion occurred in Beirut, Lebanon, caused by the ignition of 2,750 tonnes of ammonium nitrate. The chemical, confiscated in 2014 from the cargo ship MV Rhosus and stored at the Port of Beirut without adequate safety measures for six years, detonated after a fire broke out in a nearby warehouse.', 2020, 8, 4, NULL, NULL, NULL, 'day', '4 August 2020', 84, 'https://en.wikipedia.org/wiki/2020_Beirut_explosion'),
  ('Q122962941', 'Gaza War', 'The Gaza war is an armed conflict in the Gaza Strip and Israel, fought as part of the unresolved Israeli–Palestinian and Gaza–Israel conflicts. The war began on 7 October 2023, when Palestinian militant group Hamas led an attack on Israel, in which 1,195 Israelis and foreign nationals were killed and 251 were taken hostage.', 2020, NULL, NULL, NULL, NULL, NULL, 'decade', '2020s', 91, 'https://en.wikipedia.org/wiki/Gaza_war'),
  ('Q130388076', '2024 Lebanon War', 'A war between Israel and Hezbollah took place in Lebanon for about 10 weeks in 2024 amid the Middle Eastern crisis. The war began in September 2024 following nearly 12 months of conflict between Israel and Hezbollah, when the former initiated major attacks in Lebanon including an attack on pagers and electronic devices, the assassination of Hezbollah leader Hassan Nasrallah, and an aerial bombing campaign throughout the country.', 2020, NULL, NULL, 2024, 11, 27, 'decade', '2020s – 27 November 2024', 64, 'https://en.wikipedia.org/wiki/2024_Lebanon_war'),
  ('Q108891053', '2021 Beirut clashes', 'The 2021 Beirut clashes, also known as the Tayouneh Incident or Mini May 7, occurred in the Tayouneh neighborhood of the Lebanese capital of Beirut on 14 October 2021 between Hezbollah and the Amal Movement, and unidentified gunmen allegedly associated with the Lebanese Forces, and the Lebanese Armed Forces, resulting in the death of seven people and injury of 32 others, and the arrest of nine by the Lebanese Armed Forces. The violence erupted during a protest organized by Hezbollah and its allies against Tarek Bitar, the lead judge probing the 2020 explosion in the city''s port, as they…', 2021, 10, 14, NULL, NULL, NULL, 'day', '14 October 2021', 48, 'https://en.wikipedia.org/wiki/2021_Beirut_clashes'),
  ('Q121305994', '2023 Ain al-Hilweh clashes', 'On 30 July 2023, fighting broke out inside the Ain al-Hilweh Palestinian refugee camp in Lebanon after Islamist gunmen tried to assassinate Fatah militant Mahmoud Khalil, killing a companion of his instead.', 2023, 7, 30, 2023, 9, 15, 'day', '30 July 2023 – 15 September 2023', 34, 'https://en.wikipedia.org/wiki/2023_Ain_al-Hilweh_clashes'),
  ('Q124086310', 'assassination of Saleh al-Arouri', 'On 2 January 2024, Saleh al-Arouri, the deputy leader of Hamas, was killed in an Israeli strike on an office in the Dahieh suburbs of Beirut, Lebanon. The strike also killed six other individuals, including additional high-ranking Hamas militants.', 2024, 1, 2, NULL, NULL, NULL, 'day', '2 January 2024', 50, 'https://en.wikipedia.org/wiki/Assassination_of_Saleh_al-Arouri'),
  ('Q130199797', 'August 2024 Nabatieh attack', 'On August 17, 2024, Israel attacked a warehouse in Nabatieh in southern Lebanon, killing at least 11 people and injuring four others. All people killed in the attack were Syrian refugees.', 2024, 8, 17, NULL, NULL, NULL, 'day', '17 August 2024', 39, 'https://en.wikipedia.org/wiki/August_2024_Nabatieh_attack'),
  ('Q130314422', '2024 Lebanon electronic device attacks', 'On 17 and 18 September 2024, thousands of handheld pagers and hundreds of walkie-talkies intended for use by Hezbollah exploded simultaneously in two separate events across Lebanon and Syria, in an Israeli attack nicknamed Operation Grim Beeper. According to an unnamed Hezbollah official, the attack took 1,500 Hezbollah fighters out of action due to injuries.', 2024, 9, 18, 2024, 9, 19, 'day', '18 September 2024 – 19 September 2024', 73, 'https://en.wikipedia.org/wiki/2024_Lebanon_electronic_device_attacks'),
  ('Q130331542', '20 September 2024 Beirut attack', 'On 20 September 2024, Israel launched an air attack that leveled an apartment building in the Dahieh suburb of Beirut, Lebanon. The attack killed at least 45 people, including 16 Hezbollah militants, including commanders Ibrahim Aqil and Ahmed Wehbe.', 2024, 9, 20, NULL, NULL, NULL, 'day', '20 September 2024', 45, 'https://en.wikipedia.org/wiki/20_September_2024_Beirut_attack'),
  ('Q130374882', '2024 Hezbollah headquarters strike', 'On 27 September 2024, Hassan Nasrallah, the secretary-general of Hezbollah, was assassinated in an Israeli airstrike in Beirut. The strike took place while Hezbollah leaders were meeting at a headquarters located 60 feet (18 m) underground beneath residential buildings in Haret Hreik in the Dahieh suburb.', 2024, 9, 27, NULL, NULL, NULL, 'day', '27 September 2024', 63, 'https://en.wikipedia.org/wiki/2024_Hezbollah_headquarters_strike');
